// The vehicle page body, shared by the browser (vehicle.js) and the server-rendered page so that
// search engines index the same content visitors see.
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory(require('./finance-utils.js'), require('./inventory.js'), require('./showroom-card.js'));
  else root.DFVehicleView = factory(root.DF, root.DFInventory, root.DFCard);
})(typeof window !== 'undefined' ? window : globalThis, function (DF, DFInventory, DFCard) {
  const {money, escapeHtml: e, vehicleTitle} = DF;
  const {vehicleUrl, makeUrl} = DFInventory;
  const {photosOf, imageUrl, km, whatsappLink} = DFCard;
  const siteUrl = 'https://www.driving-force.co.za';
  const terms = [6, 12, 18, 24, 30, 36, 42, 48, 54, 60, 66, 72, 78, 84, 90, 96];
  const makeLabel = car => vehicleTitle({make: car.make, model: ''}).trim();
  function descriptionOf(car) {
    const mileage = km(car.mile);
    return Array.isArray(car.description) && car.description.length ? car.description : [`${car.year} ${vehicleTitle(car)}, ${car.variant}. ${car.colour} exterior, ${mileage}, ${String(car.fuelType).toLowerCase()} fuel and ${String(car.transmission).toLowerCase()} transmission. Contact our showroom for more information about this vehicle.`];
  }
  function enquiryMailto(car) {
    return 'mailto:info@drivingforce.biz?' + new URLSearchParams({subject: `Vehicle enquiry: ${car.year} ${vehicleTitle(car)} (${car.stock_code})`, body: `Hello Driving Force,\n\nI would like to enquire about the ${car.year} ${vehicleTitle(car)}, stock ${car.stock_code}. Please confirm availability and help me arrange a viewing.\n\n${siteUrl}${vehicleUrl(car)}`}).toString().replace(/\+/g, '%20');
  }
  function vehicleMarkup(car, data = {}) {
    const photos = photosOf(car).map(imageUrl), mileage = km(car.mile), description = descriptionOf(car);
    const name = e(car.year + ' ' + vehicleTitle(car)), alt = e(`${car.year} ${vehicleTitle(car)} ${car.variant} in ${car.colour}`);
    const recorded = data.retrieved ? `Inventory recorded ${e(data.retrieved)}. ` : '';
    return `<nav class="vehicle-breadcrumb" aria-label="Breadcrumb"><ol class="crumbs"><li><a href="/">Home</a></li><li><a href="/used-cars">Used cars</a></li><li><a href="${makeUrl(car.make)}">${e(makeLabel(car))}</a></li><li aria-current="page">${name}</li></ol><span>STOCK ${e(car.stock_code)}</span></nav>
      <div class="vehicle-hero">
        <div class="vehicle-gallery"><button type="button" class="photo-open" aria-label="Enlarge photo of ${e(vehicleTitle(car))}" aria-haspopup="dialog"><img class="detail-photo" src="${e(photos[0])}" alt="${alt}" width="800" height="533" fetchpriority="high"><span class="photo-expand" aria-hidden="true">${photos.length > 1 ? 'View ' + photos.length + ' photos' : 'View full photo'} <span>↗</span></span></button>${photos.length > 1 ? `<div class="photo-thumbs" role="group" aria-label="Choose a photo">${photos.map((src, i) => `<button type="button" class="photo-thumb" data-photo="${i}" aria-label="Show photo ${i + 1} of ${photos.length}" aria-pressed="${i === 0}"><img src="${e(src)}" alt="" loading="lazy" width="120" height="80"></button>`).join('')}</div>` : ''}<div class="photo-caption"><span>${e(car.colour)} exterior</span><span>Driving Force · Cape Town</span></div></div>
        <section class="vehicle-summary" aria-labelledby="vehicle-title"><p class="detail-eyebrow"><span class="red-line" aria-hidden="true"></span>${car.year} / ${e(car.body_type)}</p><h1 id="vehicle-title">${car.year} ${e(vehicleTitle(car))}</h1><p class="detail-variant">${e(car.variant)}</p><div class="vehicle-offer"><span class="detail-label">Asking price</span><strong class="detail-price">${money(car.value)}</strong></div><dl class="vehicle-key-facts">${[['Mileage', mileage], ['Transmission', car.transmission], ['Fuel type', car.fuelType]].map(([label, value]) => `<div><dt>${label}</dt><dd>${e(value)}</dd></div>`).join('')}</dl><a class="button button-red full-width vehicle-enquire" href="${e(enquiryMailto(car))}" data-vehicle="${e(car.id)}" aria-haspopup="dialog">Send an enquiry <span aria-hidden="true">↗</span></a><a class="button button-outline full-width vehicle-whatsapp-cta" href="${e(whatsappLink(car))}" target="_blank" rel="noopener noreferrer">WhatsApp 082 425 4253 <span aria-hidden="true">↗</span></a><a class="button button-outline full-width" href="/visit?vehicle=${car.id}">Visit the showroom <span aria-hidden="true">↗</span></a><a class="detail-call" href="tel:+27212038888">Or call 021 203 8888</a><a class="finance-jump" href="#vehicle-finance">Explore finance options <span aria-hidden="true">↓</span></a></section>
      </div>
      <nav class="vehicle-section-links" aria-label="Vehicle information"><a href="#vehicle-overview">Overview</a><a href="#vehicle-specifications">Specifications</a>${car.features?.length ? '<a href="#vehicle-equipment">Equipment</a>' : ''}<a href="#vehicle-finance">Finance</a></nav>
      <div class="vehicle-detail-body"><article class="vehicle-story"><section id="vehicle-overview" class="vehicle-section"><p class="detail-eyebrow">THE DETAILS</p><h2>About this ${e(car.year + ' ' + vehicleTitle(car))}.</h2><div class="vehicle-description">${description.map(p => `<p>${e(p)}</p>`).join('')}<p>This used ${e(vehicleTitle(car))} is for sale at Driving Force, a pre-owned vehicle dealer in Montague Gardens, Cape Town. View it in our showroom, arrange a test drive, or <a href="/finance?vehicle=${car.id}">apply for vehicle finance</a> online. We also take trade-ins and buy cars. <a href="${makeUrl(car.make)}">See all used ${e(makeLabel(car))} vehicles</a> in stock.</p></div></section>
        <section id="vehicle-specifications" class="vehicle-section"><h2>At a glance.</h2><dl class="detail-specs">${[['Year', car.year], ['Make', makeLabel(car)], ['Model', vehicleTitle({...car, displayName: ''}).replace(makeLabel(car), '').trim() || car.model], ['Mileage', mileage], ['Transmission', car.transmission], ['Fuel type', car.fuelType], ['Colour', car.colour], ['Body type', car.body_type], ['Variant', car.variant], ['Stock reference', car.stock_code]].map(([label, value]) => `<div><dt>${label}</dt><dd>${e(value)}</dd></div>`).join('')}</dl></section>
        ${car.features?.length ? `<section id="vehicle-equipment" class="vehicle-section"><h2>Equipment highlights.</h2><ul class="vehicle-equipment">${car.features.map(feature => `<li><span aria-hidden="true">✓</span>${e(feature)}</li>`).join('')}</ul><p class="stock-note">Equipment recorded in Driving Force’s original listing. Please confirm current fitment with the showroom.</p></section>` : ''}
        <p class="stock-note">${recorded}Please confirm current mileage, price and availability with our team.</p></article>
        <section id="vehicle-finance" class="vehicle-finance" aria-labelledby="estimate-title"><p class="detail-eyebrow">PLAN YOUR NEXT DRIVE</p><h2 id="estimate-title">Make it yours.</h2><p class="form-intro">Adjust the figures to explore a monthly payment.</p><form id="vehicle-estimate" class="estimate-form"><div class="form-grid"><label>Vehicle price<div class="line-input"><span>R</span><input name="price" type="number" readonly value="${car.value}" min="1" max="10000000" step="any" required inputmode="decimal"></div></label><label>Deposit<div class="line-input"><span>R</span><input name="deposit" type="number" value="0" min="0" step="any" required inputmode="decimal"></div></label><label>Net trade-in value<div class="line-input"><span>R</span><input name="tradeIn" type="number" value="0" min="0" step="any" required inputmode="decimal"></div></label><label>Annual interest rate<div class="line-input"><input name="rate" type="number" value="12" min="0" max="30" step="any" required inputmode="decimal"><span>%</span></div></label><label class="span-two">Repayment term<select name="term">${terms.map(term => `<option value="${term}" ${term === 72 ? 'selected' : ''}>${term} months</option>`).join('')}</select></label></div><p id="estimate-error" class="form-error" role="status"></p><div class="estimate-result" aria-live="polite"><span>Estimated monthly payment</span><p><strong id="estimate-monthly">—</strong><span> / month</span></p></div><a class="button button-red full-width" href="/finance?vehicle=${car.id}" id="apply-finance">Apply for finance <span>↗</span></a><dl class="estimate-totals"><div><dt>Amount financed</dt><dd id="estimate-principal">—</dd></div><div><dt>Total interest</dt><dd id="estimate-interest">—</dd></div><div><dt>Total loan repayments</dt><dd id="estimate-total">—</dd></div></dl><p class="estimate-note">Illustrative estimate, subject to lender approval. Excludes fees, insurance and balloon payments. Net trade-in value is the amount available after settling any existing vehicle loan.</p><p class="estimate-note">Complete the full application here on our website.</p></form></section></div>
      <div class="vehicle-visit"><div><p class="detail-eyebrow">SEE IT. WANT IT. DRIVE IT.</p><h2>See it for yourself.</h2><p>21 Montague Drive, Montague Gardens, Cape Town.</p></div><div class="vehicle-visit-actions"><a class="button button-black" href="/visit?vehicle=${car.id}">Plan your visit <span aria-hidden="true">↗</span></a><a class="phone-link" href="tel:+27212038888">Call 021 203 8888</a></div></div>
      <dialog class="vehicle-photo-dialog" aria-label="${e(vehicleTitle(car))} photo"><div class="photo-dialog-top"><span>${name}</span><button type="button" class="photo-close" aria-label="Close photo">Close <span aria-hidden="true">×</span></button></div><div class="dialog-photo"><img class="dialog-image" src="${e(photos[0])}" alt="${alt}" width="800" height="533">${photos.length > 1 ? '<button type="button" class="photo-step photo-prev" aria-label="Previous photo">‹</button><button type="button" class="photo-step photo-next" aria-label="Next photo">›</button>' : ''}</div><p>${photos.length > 1 ? '<span class="photo-count">1 / ' + photos.length + '</span> · ' : ''}Stock ${e(car.stock_code)} · ${e(car.colour)} exterior</p></dialog>`;
  }
  return {vehicleMarkup, descriptionOf, enquiryMailto, makeLabel, siteUrl};
});
